example.code:
#include <iostream>
#include <array>

int main() {
    // Initialize a tracker array for values 1..99 with false
    constexpr int MAX_NUM = 99;
    std::array<bool, MAX_NUM> isCovered = {}; // modern C++17 value-initialization (all false)

    int number = 0;
    while (std::cin >> number && number != 0) {
        if (number >= 1 && number <= MAX_NUM) {
            isCovered[number - 1] = true;
        }
    }

    bool allCovered = true;
    for (int i = 0; i < MAX_NUM; ++i) {
        if (!isCovered[i]) {
            allCovered = false;
            break;
        }
    }

    if (allCovered) {
        std::cout << "The tickets cover all numbers" << std::endl;
    } else {
        std::cout << "The tickets don't cover all numbers" << std::endl;
    }

    return 0;
}

