#include <iostream>
#include <string>
#include <vector>

int main() {
    const std::string suits[] = {"Spades", "Hearts", "Diamonds", "Clubs"};
    const std::string ranks[] = {"Ace", "2", "3", "4", "5", "6", "7", "8", "9", "10", "Jack", "Queen", "King"};

    // Test cards as listed in the textbook sample trace
    int sampleCards[] = {6, 48, 11, 24};

    for (int card : sampleCards) {
        std::string suit = suits[card / 13];
        std::string rank = ranks[card % 13];
        std::cout << "Card number " << card << ": " << rank << " of " << suit << std::endl;
    }

    return 0;
}
